<?php

declare(strict_types=1);

final class GBDBWeek91To92Benchmarks {
    private string $instance; private string $base='week91_92_bench'; private string $table='bench_rows'; private int $rows;
    public function __construct(int $rows=10){$this->rows=max(1,min(100,$rows));$this->instance='bench_w91_92_'.substr(hash('sha1',(string)microtime(true)),0,8);}
    public function run():array{$old=GBDB::getActualInstance();$out=[];try{GBDB::createInstance($this->instance);GBDB::setInstance($this->instance);GBDB::create($this->base,$this->table,true,['title'=>'string','group_id'=>'int','score'=>'float','body'=>'text']);$out['insert']=$this->bench(fn()=> $this->insertRows(1));$out['bulk_insert']=$this->bench(fn()=> $this->insertRows($this->rows));$out['read_by_id']=$this->bench(fn()=>GBDB::get($this->base,$this->table,'id',1));$out['read_by_index_candidate']=$this->bench(fn()=>GBDB::get($this->base,$this->table,'group_id',5));$out['range_query']=$this->bench(fn()=> $this->rangeQuery(2,8));$out['composite_index_prepare']=$this->bench(fn()=>['ok'=>method_exists('GBDB','createCompositeIndex'),'prepared'=>true]);$out['full_scan']=$this->bench(fn()=>GBDB::get($this->base,$this->table));$out['aggregation']=$this->bench(fn()=> $this->aggregate());$out['search']=$this->bench(fn()=>GBDB::fullTextSearch($this->base,$this->table,'benchmark'));$out['backup']=$this->bench(fn()=>['ok'=>method_exists('GBDB','tableBackup'),'prepared'=>true]);$out['transaction']=$this->bench(fn()=>['ok'=>method_exists('GBDB','beginTransaction'),'prepared'=>true]);$out['wal_recovery']=$this->bench(fn()=>['ok'=>method_exists('GBDB','recoverTable'),'prepared'=>true]);$out['queue']=$this->bench(fn()=>['ok'=>method_exists('GBDB','enqueueJob'),'prepared'=>true]);$out['media_metadata']=$this->bench(fn()=>['ok'=>method_exists('GBDB','orphanMediaCleanup'),'prepared'=>true]);}finally{GBDB::setInstance($old);}return ['ok'=>true,'rows'=>$this->rows,'benchmarks'=>$out];}
    private function bench(callable $fn):array{$start=hrtime(true);$result=$fn();return ['ms'=>round((hrtime(true)-$start)/1000000,3),'ok'=>$result!==false&&$result!==null,'sample'=>is_array($result)?array_slice($result,0,3):$result];}
    private function insertRows(int $count):array{$ids=[];for($i=0;$i<$count;$i++)$ids[]=GBDB::insert($this->base,$this->table,['title'=>'Benchmark '.$i,'group_id'=>$i%10,'score'=>($i%100)/10,'body'=>'benchmark search payload '.$i]);return $ids;}
    private function rangeQuery(int $min,int $max):array{return array_values(array_filter(GBDB::get($this->base,$this->table),fn($row)=>((float)($row['score']??0))>=($min/10)&&((float)($row['score']??0))<=($max/10)));}
    private function aggregate():array{$sum=0.0;$count=0;foreach(GBDB::get($this->base,$this->table) as $row){$sum+=(float)($row['score']??0);$count++;}return ['count'=>$count,'avg_score'=>$count>0?$sum/$count:0];}
}
if (basename(__FILE__) === basename((string)($_SERVER['SCRIPT_FILENAME'] ?? ''))) { require_once dirname(__DIR__,3).'/gbdb.php'; header('Content-Type: application/json; charset=utf-8'); echo json_encode((new GBDBWeek91To92Benchmarks((int)($_GET['rows']??10)))->run(), JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES); }
